Main {

    U = 2.*(U-.5*R)/R.y;
    float q = exp(-2.*length(U))/(dot(U,U)+(1.-.8*cos(atan(U.y,U.x))));
    Q = sin(.5*q+vec4(1,2,3,4));
    q *= 6.;    
    float m = A(gl_FragCoord.xy).x/float(1+iFrame);
    Q = mix(Q,sin(-3.1+.5*m+vec4(1,2,3,4)),clamp(m,0.,1.));
    Q *= smoothstep(0.,1.5*fwidth(q),abs(sin(q)));

}

#define R iResolution.xy
#define A(U) texture(iChannel0,(U)/R)
#define Main void mainImage(out vec4 Q, in vec2 U)

vec4 hash(vec4 p4)
{
	p4 = fract(p4  * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return fract((p4.xxyz+p4.yzzw)*p4.zywx);
}

Main {
    Q = A(U);
    vec4 h = hash(vec4(U,iTime,iFrame));
    float a = h.x*3.141592658*2.;
    vec2 u = U;
    vec2 v = h.y*vec2(cos(a),sin(a));

    for (float i = 0.; i < 300.; i++) {
        Q += 10000.*step(length(u-.5*R),2.)*
            exp(-20.*length(v-vec2(-1.,0)));
        u += 2.*v;
        v += .2*(hash(vec4(u,i,iFrame)).xy*2.-1.);
    }

}
